const{div:div,span:span,anchor:anchor,heading:heading,paragraph:paragraph,text:text}=treeloomComponents,columns=4,classes={grid:"project-grid",layer:"grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4",row:"contents",emptyTile:"tile tile-empty invisible",tile:"tile rounded-lg border border-rule bg-foreground/4 transition duration-150 hover:-translate-y-1 hover:border-accent hover:shadow-lg focus-within:border-accent motion-reduce:transition-none motion-reduce:hover:translate-y-0",link:"tile-link block h-full p-4 text-foreground no-underline",icon:"flex size-10 items-center justify-center rounded-full bg-accent",letter:"tile-icon-letter font-heading text-lg font-bold text-background",title:"mt-3 mb-1 text-lg",description:"m-0 text-sm/relaxed text-muted"},tileContent=e=>anchor(e.href,[div([span([text(e.title[0].toUpperCase())],classes.letter)],classes.icon),heading(3,[text(e.title)],classes.title),paragraph(e.description,[],classes.description)],classes.link,{target:"_blank"}),projectGrid=e=>{const t=Math.ceil(e.length/4),r=treeloomMatrix.buildMatrix({x:4,y:t,z:1},{matrix:{attributes:{className:classes.grid}},z:{attributes:{className:classes.layer}},y:{attributes:{className:classes.row}},x:{attributes:{className:classes.emptyTile}}});return e.forEach((e,t)=>{const s=treeloomMatrix.getDomItemFromPoint(treeloomMatrix.point(t%4,Math.floor(t/4)),r);s.attributes.className=classes.tile,treeloom.appendChild(s,tileContent(e))}),r};export default projectGrid;